func enrichAnimalsOptimized(a *models.Animals, c buffalo.Context, withTreatments bool) (*models.Animals, error) {
	// If nothing to enrich, don't preload
	if len(*a) == 0 {
		return a, nil
	}

	tx, ok := c.Value("tx").(*pop.Connection)
	if !ok {
		return nil, fmt.Errorf("no transaction found")
	}

	// Get all IDs to fetch in bulk
	animalIds := make([]string, len(*a))
	// Seen-sets dedupe the distinct relation ids below in O(1) per row;
	// the previous containsUUID scans were O(n^2) over large listings.
	seenTypes := map[uuid.UUID]struct{}{}
	seenAges := map[uuid.UUID]struct{}{}
	seenDiscoveries := map[uuid.UUID]struct{}{}
	seenIntakes := map[uuid.UUID]struct{}{}
	seenOuttakes := map[uuid.UUID]struct{}{}

	animalTypeIds := make([]uuid.UUID, 0, len(*a))
	animalAgeIds := make([]uuid.UUID, 0, len(*a))
	discoveryIds := make([]uuid.UUID, 0, len(*a))
	intakeIds := make([]uuid.UUID, 0, len(*a))
	outtakeIds := make([]uuid.UUID, 0, len(*a))

	add := func(set map[uuid.UUID]struct{}, ids []uuid.UUID, id uuid.UUID) []uuid.UUID {
		if _, dup := set[id]; dup {
			return ids
		}
		set[id] = struct{}{}
		return append(ids, id)
	}

	for i, animal := range *a {
		animalIds[i] = fmt.Sprintf("%d", animal.ID)

		// Collect unique IDs for bulk fetching
		animalTypeIds = add(seenTypes, animalTypeIds, animal.AnimaltypeID)
		animalAgeIds = add(seenAges, animalAgeIds, animal.AnimalageID)
		discoveryIds = add(seenDiscoveries, discoveryIds, animal.DiscoveryID)
		intakeIds = add(seenIntakes, intakeIds, animal.IntakeID)
		if animal.OuttakeID.Valid {
			outtakeIds = add(seenOuttakes, outtakeIds, animal.OuttakeID.UUID)
		}
	}

	// Bulk fetch all related data
	animalTypes := make(map[uuid.UUID]models.Animaltype)
	if len(animalTypeIds) > 0 {
		var ats models.Animaltypes
		if err := tx.Where("id IN (?)", animalTypeIds).All(&ats); err != nil {
			return nil, err
		}
		for _, at := range ats {
			animalTypes[at.ID] = at
		}
	}

	animalAges := make(map[uuid.UUID]models.Animalage)
	if len(animalAgeIds) > 0 {
		var ags models.Animalages
		if err := tx.Where("id IN (?)", animalAgeIds).All(&ags); err != nil {
			return nil, err
		}
		for _, ag := range ags {
			animalAges[ag.ID] = ag
		}
	}

	discoveries := make(map[uuid.UUID]models.Discovery)
	if len(discoveryIds) > 0 {
		var dts models.Discoveries
		if err := tx.Where("id IN (?)", discoveryIds).All(&dts); err != nil {
			return nil, err
		}
		for _, dt := range dts {
			discoveries[dt.ID] = dt
		}
	}

	intakes := make(map[uuid.UUID]models.Intake)
	if len(intakeIds) > 0 {
		var its models.Intakes
		if err := tx.Where("id IN (?)", intakeIds).All(&its); err != nil {
			return nil, err
		}
		for _, it := range its {
			intakes[it.ID] = it
		}
	}

	outtakes := make(map[uuid.UUID]models.Outtake)
	outtakeTypes := make(map[uuid.UUID]models.Outtaketype)
	if len(outtakeIds) > 0 {
		var ots models.Outtakes
		if err := tx.Where("id IN (?)", outtakeIds).All(&ots); err != nil {
			return nil, err
		}
		for _, ot := range ots {
			outtakes[ot.ID] = ot
		}

		// Also fetch outtake types
		outtakeTypeIds := make([]uuid.UUID, 0, len(ots))
		seenOuttakeTypes := map[uuid.UUID]struct{}{}
		for _, ot := range ots {
			outtakeTypeIds = add(seenOuttakeTypes, outtakeTypeIds, ot.TypeID)
		}
		if len(outtakeTypeIds) > 0 {
			var otTypes models.Outtaketypes
			if err := tx.Where("id IN (?)", outtakeTypeIds).All(&otTypes); err != nil {
				return nil, err
			}
			for _, ott := range otTypes {
				outtakeTypes[ott.ID] = ott
			}
		}
	}

	// Fetch today's treatments for all animals in one query
	treatments := make(map[int]models.Treatments)
	if withTreatments && len(animalIds) > 0 {
		now := time.Now()
		nowDt := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
		tmrDt := nowDt.AddDate(0, 0, 1)

		var allTreatments models.Treatments
		// Parameterized placeholder expansion — string-building the list
		// would interpolate values into SQL text.
		if err := tx.Where("animal_id IN (?)", animalIds).Where("date >= ?", nowDt).Where("date < ?", tmrDt).Order("animal_id").All(&allTreatments); err != nil {
			return nil, err
		}
		// Group treatments by animal ID
		for _, t := range allTreatments {
			treatments[t.AnimalID] = append(treatments[t.AnimalID], t)
		}
	}

	// Populate all animals with the fetched data
	for i := range *a {
		(*a)[i].Animaltype = animalTypes[(*a)[i].AnimaltypeID]
		(*a)[i].Animalage = animalAges[(*a)[i].AnimalageID]
		(*a)[i].Discovery = discoveries[(*a)[i].DiscoveryID]
		(*a)[i].Intake = intakes[(*a)[i].IntakeID]
		(*a)[i].Treatments = treatments[(*a)[i].ID]

		if (*a)[i].OuttakeID.Valid {
			outtake := outtakes[(*a)[i].OuttakeID.UUID]
			outtake.Type = outtakeTypes[outtake.TypeID]
			(*a)[i].Outtake = &outtake
		}
	}

	return a, nil
}

// Helper function to check if UUID slice contains a UUID
func containsUUID(slice []uuid.UUID, id uuid.UUID) bool {
	for _, v := range slice {
		if v == id {
			return true
		}
	}
	return false
}

// EnrichAnimals load deps of an animal record required for general listings
// This is the original function kept for compatibility
func EnrichAnimals(a *models.Animals, c buffalo.Context) (*models.Animals, error) {
	// If nothing to enrich, don't preload
	if len(*a) == 0 {
		return a, nil
	}
	// preload types
	// Types
	atsMap := make(map[uuid.UUID]models.Animaltype)
	if ats, err := animalTypes(c); err != nil {
		return nil, err
	} else {
		for _, at := range *ats {
			atsMap[at.ID] = at
		}
	}
	// Ages
	agsMap := make(map[uuid.UUID]models.Animalage)
	if ags, err := animalages(c); err != nil {
		return nil, err
	} else {
		for _, a := range *ags {
			agsMap[a.ID] = a
		}
	}
	// Outtake Type
	otkMap := make(map[uuid.UUID]models.Outtaketype)
	if otk, err := outtakeTypes(c); err != nil {
		return nil, err
	} else {
		for _, ot := range *otk {
			otkMap[ot.ID] = ot
		}
	}

	// Preload all sub items
	intakeIDS := []uuid.UUID{}
	outtakeIDS := []uuid.UUID{}
	discoveryIDS := []uuid.UUID{}

	// Preload all outtakes

	animalsID := []string{}
	// 1st pass - populate IDS / base type
	for i := 0; i < len(*a); i++ {
		(*a)[i].Animalage = agsMap[(*a)[i].AnimalageID]
		(*a)[i].Animaltype = atsMap[(*a)[i].AnimaltypeID]
		intakeIDS = append(intakeIDS, (*a)[i].IntakeID)
		discoveryIDS = append(discoveryIDS, (*a)[i].DiscoveryID)
		if (*a)[i].OuttakeID.Valid {
			outtakeIDS = append(outtakeIDS, (*a)[i].OuttakeID.UUID)
		}
		animalsID = append(animalsID, fmt.Sprintf("%d", (*a)[i].ID))

		//c.Logger().Debugf("Animal %d: intake %v", (*a)[i].ID, (*a)[i].IntakeID)
	}

	tx, ok := c.Value("tx").(*pop.Connection)
	if !ok {
		return nil, fmt.Errorf("no transaction found")
	}

	now := time.Now()
	nowDt := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
	tmrDt := nowDt.AddDate(0, 0, 1)

	// Preload all today treatments
	treaments := models.Treatments{}
	tmap := map[int]models.Treatments{}
	if err := tx.Where("date >= ?", nowDt).Where("date < ?", tmrDt).Where(
		fmt.Sprintf("animal_id IN (%s)", strings.Join(animalsID, ","))).Order("animal_id desc").All(&treaments); err != nil {
		return nil, c.Error(http.StatusNotFound, err)
	}
	// remap by animal id
	for _, t := range treaments {
		tmap[t.AnimalID] = append(tmap[t.AnimalID], t)
	}
	// populate animals
	for i := 0; i < len(*a); i++ {
		(*a)[i].Treatments = tmap[(*a)[i].ID]
	}

	dts := &models.Discoveries{}
	if len(discoveryIDS) > 0 {
		if err := tx.Where("ID in (?)", discoveryIDS).All(dts); err != nil {
			return nil, err
		}
	}
	// discovery map
	discoveryMap := make(map[uuid.UUID]models.Discovery)
	for _, i := range *dts {
		discoveryMap[i.ID] = i
	}

	its := &models.Intakes{}
	if err := tx.Where("ID in (?)", intakeIDS).All(its); err != nil {
		return nil, err
	}
	// Intake map
	intakeMap := make(map[uuid.UUID]models.Intake)
	for _, i := range *its {
		intakeMap[i.ID] = i
	}

	ots := &models.Outtakes{}
	if len(outtakeIDS) > 0 {
		if err := tx.Where("ID in (?)", outtakeIDS).All(ots); err != nil {
			return nil, err
		}
	}
	// outtake map
	outtakeMap := make(map[uuid.UUID]models.Outtake)
	for _, i := range *ots {
		outtakeMap[i.ID] = i
	}

	// 2nd pass: Populate intakes
	// 1st pass - populate IDS
	for i := 0; i < len(*a); i++ {
		(*a)[i].Intake = intakeMap[(*a)[i].IntakeID]
		(*a)[i].Discovery = discoveryMap[(*a)[i].DiscoveryID]
		if (*a)[i].OuttakeID.Valid {
			outtake := outtakeMap[(*a)[i].OuttakeID.UUID]
			outtake.Type = otkMap[outtake.TypeID]
			(*a)[i].Outtake = &outtake
		}
	}

	return a, nil
}

type animalFinder interface {
	Find(model interface{}, id interface{}) error
}

// findOrIgnoreMissing loads one related record, tolerating dangling foreign
// keys: a missing reference row leaves dst zero-valued instead of failing the
// whole request with a 404. Any other DB error is returned.
func findOrIgnoreMissing(q animalFinder, dst interface{}, id interface{}) error {
	err := q.Find(dst, id)
	if err != nil && errors.Is(err, sql.ErrNoRows) {
		return nil
	}
	return err
}

// EnrichAnimal load all deps of an animal record
func EnrichAnimal(a *models.Animal, c buffalo.Context) (*models.Animal, error) {
	tx, ok := c.Value("tx").(*pop.Connection)
	if !ok {
		return nil, fmt.Errorf("no transaction found")
	}

	if err := findOrIgnoreMissing(tx, &a.Animalage, a.AnimalageID); err != nil {
		return nil, err
	}
	if err := findOrIgnoreMissing(tx, &a.Animaltype, a.AnimaltypeID); err != nil {
		return nil, err
	}
	if err := findOrIgnoreMissing(tx.Eager(), &a.Discovery, a.DiscoveryID); err != nil {
		return nil, err
	}
	if err := findOrIgnoreMissing(tx.Eager(), &a.Intake, a.IntakeID); err != nil {
		return nil, err
	}

	if err := tx.Eager().Where("animal_id = ?", a.ID).Order("date desc").All(&a.Cares); err != nil {
		return nil, c.Error(http.StatusNotFound, err)
	}
	if err := tx.Eager().Where("animal_id = ?", a.ID).Order("date desc").All(&a.VetVisits); err != nil {
		return nil, c.Error(http.StatusNotFound, err)
	}
	if err := tx.Eager().Where("animal_id = ?", a.ID).Order("date desc").All(&a.Treatments); err != nil {
		return nil, c.Error(http.StatusNotFound, err)
	}

	if a.OuttakeID.Valid {
		c.Logger().Debugf("Loading outtake %v", a.OuttakeID)
		a.Outtake = &models.Outtake{}
		if err := findOrIgnoreMissing(tx.Eager(), a.Outtake, a.OuttakeID); err != nil {
			return nil, err
		}
		// Fully reset a missing outtake so templates see no outtake at all.
		if a.Outtake.ID == uuid.Nil {
			a.Outtake = nil
		}
	}
	return a, nil
}

func (v AnimalsResource) loadAnimal(animal_id string, c buffalo.Context) (*models.Animal, error) {
	a := &models.Animal{}

	tx, ok := c.Value("tx").(*pop.Connection)
	if !ok {
		return nil, fmt.Errorf("no transaction found")
	}
	if err := tx.Find(a, animal_id); err != nil {
		return nil, c.Error(http.StatusNotFound, err)
	}
	return EnrichAnimal(a, c)
}

// List gets all Animals. This function is mapped to the path
// GET /animals
func (v AnimalsResource) List(c buffalo.Context) error {
	// Get the DB connection from the context
	tx, ok := c.Value("tx").(*pop.Connection)
	if !ok {
		return fmt.Errorf("no transaction found")
	}

	animalYearNumber := c.Param("animal_year_number")
	if len(animalYearNumber) > 0 {
		c.Logger().Debug("animalYearNumber:", animalYearNumber)
		matches := AnimalYearNumberRegEx.FindStringSubmatch(animalYearNumber)
		if matches == nil {
			return fmt.Errorf("invalid year number: %s", animalYearNumber)
		}
		c.Logger().Debug("animalYearNumber regex matches:", matches)
		q := tx.Where("YearNumber = ?", matches[1])
		if len(matches) == 4 && len(matches[3]) == 2 {
			q = q.Where("Year = ?", fmt.Sprintf("20%s", matches[3]))
		}

		animal := models.Animal{}
		err := q.Order("ID desc").First(&animal)
		if err == nil {
			return c.Redirect(http.StatusSeeOther, "/animals/%v", animal.ID)
		}
	}

	animalID := c.Param("animal_id")
	if len(animalID) > 0 {
		exists, err := tx.Where("ID = ?", animalID).Exists(&models.Animal{})
		if err != nil {
			return err
		}
		if exists {
			return c.Redirect(http.StatusSeeOther, "/animals/%v", animalID)
		}
		// for message
		data := map[string]interface{}{
			"animalID": animalID,
		}
		c.Flash().Add("danger", T.Translate(c, "animal.not.found", data))
	}

	animals := &models.Animals{}

	// Paginate results. Params "page" and "per_page" control pagination.
	// Default values are "page=1" and "per_page=20".
	q := tx.PaginateFromParams(c.Params())

	// Search filters (AND-combined); shortcuts above take precedence.
	sp := animalSearchParamsFrom(c)
	var err error
	if q, err = applyAnimalSearchFilters(tx, currentLang(c), q, sp); err != nil {
		return err
	}

	// Retrieve all Animals from the DB (sort param via whitelist, default ID desc)
	q = applyAnimalSort(q, c)
	if err := q.All(animals); err != nil {
		return err
	}

	// Preload required for "list"
	if _, err := EnrichAnimalsOptimized(animals, c); err != nil {
		return err
	}

	return responder.Wants("html", func(c buffalo.Context) error {
		// Filter panel option lists + sticky values
		if err := setupAnimalSearchContext(c, sp); err != nil {
			return err
		}

		// Add the paginator to the context so it can be used in the template.
		c.Set("pagination", q.Paginator)

		c.Set("animals", animals)
		return c.Render(http.StatusOK, r.HTML("/animals/index.plush.html"))
	}).Wants("json", func(c buffalo.Context) error {
		return c.Render(200, r.JSON(animals))
	}).Wants("xml", func(c buffalo.Context) error {
		return c.Render(200, r.XML(animals))
	}).Respond(c)
}

// Show gets the data for one Animal. This function is mapped to
// the path GET /animals/{animal_id}
func (v AnimalsResource) Show(c buffalo.Context) error {
	// Load animal
	animal, err := v.loadAnimal(c.Param("animal_id"), c)
	if err != nil {
		return err
	}

	//c.Logger().Debugf("Loaded animal: %v", animal)

	return responder.Wants("html", func(c buffalo.Context) error {
		c.Set("animal", animal)
		if tx, ok := c.Value("tx").(*pop.Connection); ok {
			c.Set("speciesTypeMismatch", animalSpeciesTypeMismatch(tx, animal))
		}

		// Full (host-aware) guest form URL shown under the QR code in the
		// show view: same scheme+host as the page itself.
		c.Set("guestFormURL", guestStatusURL(guestScheme(c.Request()), c.Request().Host, animal.YearNumberFormatted(), "", ""))

		// guestNoPhone: no discoverer phone recorded for this animal — the
		// phone-gated guest form can never succeed, so the QR deep link is
		// the ONLY way to open the status view. The show template surfaces
		// this so intake staff can point it out to the finder.
		if tx, ok := c.Value("tx").(*pop.Connection); ok {
			if stored, err := guestStoredPhone(tx, animal); err == nil && stored == "" {
				c.Set("guestNoPhone", true)
			}
		}

		// Audit tab data: admin only, server-side pagination over the
		// animal_audits records of this animal.
		if user := GetCurrentUser(c); user != nil && user.Admin {
			if tx, ok := c.Value("tx").(*pop.Connection); ok {
				audits := &models.AnimalAudits{}
				q := tx.Where("animal_id = ?", animal.ID).
					PaginateFromParams(c.Params()).
					Order("created_at desc, id desc")
				if err := q.All(audits); err != nil {
					return err
				}
				c.Set("audits", audits)
				c.Set("pagination", q.Paginator)
			}
		}

		return c.Render(http.StatusOK, r.HTML("/animals/show.plush.html"))
	}).Wants("json", func(c buffalo.Context) error {
		return c.Render(200, r.JSON(animal))
	}).Wants("xml", func(c buffalo.Context) error {
		return c.Render(200, r.XML(animal))
	}).Respond(c)
}

