// Create adds a Animal to the DB. This function is mapped to the
// path POST /animals
func (v AnimalsResource) Create(c buffalo.Context) error {
	ac := struct {
		AnimalCount int
	}{}

	// Bind extra count param
	if err := c.Bind(&ac); err != nil {
		return err
	}

	// Get the DB connection from the context
	tx, ok := c.Value("tx").(*pop.Connection)
	if !ok {
		return fmt.Errorf("no transaction found")
	}

	animals := models.Animals{}

	type registerYearNumber struct {
		Year       nulls.Int `db:"Year"`
		YearNumber nulls.Int `db:"YearNumber"`
	}

	ryn := registerYearNumber{}
	if err := tx.Eager().RawQuery("SELECT MAX(Year) as 'Year', MAX(yearNumber)+1 as 'YearNumber' from animals where year = ?", time.Now().Year()).First(&ryn); err != nil {
		return err
	}

	if !ryn.Year.Valid {
		ryn.Year.Int = time.Now().Year()
	}
	if !ryn.YearNumber.Valid {
		ryn.YearNumber.Int = 1
	}

	for i := 0; i < ac.AnimalCount; i++ {
		animal := &models.Animal{}
		// Bind animal to the html form elements
		if err := c.Bind(animal); err != nil {
			return err
		}
		// Normalize possibly-localized species input back to canonical (Option A)
		animal.Species = resolveReferenceInput(c, "species", animal.Species)
		if err := completeAndValidateSpeciesType(tx, animal); err != nil {
			return c.Error(http.StatusUnprocessableEntity, err)
		}
		// Set discovery date
		animal.IntakeDate = animal.Intake.Date

		// Set year+Number
		animal.Year = ryn.Year.Int
		animal.YearNumber = ryn.YearNumber.Int
		ryn.YearNumber.Int++

		// Add remark
		if ac.AnimalCount > 1 {
			animal.Intake.Remarks = nulls.NewString(
				animal.Intake.Remarks.String +
					fmt.Sprintf("( %d / %d )",
						i+1,
						ac.AnimalCount))
		}

		// Validate the data from the html form
		// 2 steps
		verrs, err := tx.Eager().ValidateAndCreate(&animal.Discovery)
		if err != nil {
			return err
		}
		if !verrs.HasAny() {
			c.Logger().Debugf("Animal: %v", animal)

			verrs, err = tx.Eager().ValidateAndCreate(animal)
			if err != nil {
				return err
			}
		}

		if verrs.HasAny() {
			return responder.Wants("html", func(c buffalo.Context) error {
				// Make the errors available inside the html template
				c.Set("errors", verrs)

				// Render again the new.html template that the user can
				// correct the input.
				c.Set("animal", animal)

				return c.Render(http.StatusUnprocessableEntity, r.HTML("/animals/new.plush.html"))
			}).Wants("json", func(c buffalo.Context) error {
				return c.Render(http.StatusUnprocessableEntity, r.JSON(verrs))
			}).Wants("xml", func(c buffalo.Context) error {
				return c.Render(http.StatusUnprocessableEntity, r.XML(verrs))
			}).Respond(c)
		}

		animals = append(animals, *animal)

		// Audit log: animal creation (best effort)
		auditAnimalChange(c, tx, animal.ID, models.AuditEntityAnimal, auditEntityID(animal.ID), models.AuditActionCreate, nil, auditAnimalProjection(*animal))
		auditAnimalChange(c, tx, animal.ID, models.AuditEntityDiscovery, animal.DiscoveryID.String(), models.AuditActionCreate, nil, auditDiscoveryProjection(animal.Discovery))
		auditAnimalChange(c, tx, animal.ID, models.AuditEntityDiscoverer, animal.Discovery.DiscovererID.String(), models.AuditActionCreate, nil, animal.Discovery.Discoverer)
		if animal.IntakeID != uuid.Nil {
			auditAnimalChange(c, tx, animal.ID, models.AuditEntityIntake, animal.IntakeID.String(), models.AuditActionCreate, nil, animal.Intake)
		}

		// Publish animal_discovered event
		if err := PublishAnimalDiscoveredEvent(tx, animal, GetCurrentUser(c)); err != nil {
			c.Logger().Warnf("Failed to publish animal_discovered event: %v", err)
		}
		// Full-state event seeds the console's state-hash chain for the new
		// animal (deduped against any identical existing snapshot).
		publishAnimalStateEventWarn(c, tx, animal.ID)
	}

	// Annual statistics tables count animals: drop the per-year cache.
	InvalidateAnnualStatsCache()

	return responder.Wants("html", func(c buffalo.Context) error {
		// If there are no errors set a success message
		c.Flash().Add("success", T.Translate(c, "animal.created.success"))
		if ac.AnimalCount == 1 {
			// and redirect to the show page
			return c.Redirect(http.StatusSeeOther, "/animals/%v", animals[ac.AnimalCount-1].ID)
		}
		return c.Redirect(http.StatusSeeOther, "/animals/")
	}).Wants("json", func(c buffalo.Context) error {
		return c.Render(http.StatusCreated, r.JSON(animals))
	}).Wants("xml", func(c buffalo.Context) error {
		return c.Render(http.StatusCreated, r.XML(animals))
	}).Respond(c)
}

func setupContext(c buffalo.Context) error {
	at, err := animalTypes(c)
	if err != nil {
		return err
	}
	c.Set("selectAnimalTypes", animalTypesToSelectables(at, currentLang(c), c.Value("tx").(*pop.Connection)))

	aa, err := animalages(c)
	if err != nil {
		return err
	}
	c.Set("selectAnimalages", animalagesToSelectables(aa, currentLang(c), c.Value("tx").(*pop.Connection)))

	ot, err := outtakeTypes(c)
	if err != nil {
		return err
	}
	c.Set("selectOuttaketype", outtakeTypesToSelectables(ot, currentLang(c), c.Value("tx").(*pop.Connection)))

	c.Set("selectFeedingPeriod", selectFeedingPeriod())

	z, err := zones(c)
	if err != nil {
		return err
	}
	c.Set("selectZone", zonesToSelectables(z, currentLang(c), c.Value("tx").(*pop.Connection)))

	ec, err := entryCauses(c)
	if err != nil {
		return err
	}
	c.Set("selectEntryCause", entryCausesToSelectables(ec, false, currentLang(c), c.Value("tx").(*pop.Connection)))

	return nil
}

// Edit renders a edit form for a Animal. This function is
// mapped to the path GET /animals/{animal_id}/edit
func (v AnimalsResource) Edit(c buffalo.Context) error {
	if err := setupContext(c); err != nil {
		return err
	}

	// Load animal
	animal, err := v.loadAnimal(c.Param("animal_id"), c)
	if err != nil {
		return err
	}

	c.Set("animal", animal)
	return c.Render(http.StatusOK, r.HTML("/animals/edit.plush.html"))
}

// Update changes a Animal in the DB. This function is mapped to
// the path PUT /animals/{animal_id}
func (v AnimalsResource) Update(c buffalo.Context) error {
	// Get the DB connection from the context
	tx, ok := c.Value("tx").(*pop.Connection)
	if !ok {
		return fmt.Errorf("no transaction found")
	}

	// Load animal
	animal, err := v.loadAnimal(c.Param("animal_id"), c)
	if err != nil {
		return err
	}

	// Audit snapshots taken before binding mutates the loaded records.
	// Shallow copies: association structs are value types; the Outtake
	// pointer is copied explicitly.
	oldAnimal := *animal
	oldDiscovery := animal.Discovery
	oldIntake := animal.Intake
	var oldOuttake *models.Outtake
	if animal.Outtake != nil {
		oc := *animal.Outtake
		oldOuttake = &oc
	}
	oldDiscoverer := animal.Discovery.Discoverer

	// save original cage
	originalCage := animal.Cage
	originalFeeding := animal.Feeding
	originalOuttakeID := animal.OuttakeID

	// Bind Animal to the html form elements
	if err := c.Bind(animal); err != nil {
		return err
	}
	// Normalize possibly-localized species input back to canonical (Option A)
	animal.Species = resolveReferenceInput(c, "species", animal.Species)
	if err := completeAndValidateSpeciesType(tx, animal); err != nil {
		return c.Error(http.StatusUnprocessableEntity, err)
	}

	// Decode Feeding times
	feedingTimes := struct {
		AnimalFeedingStartTime        string
		AnimalFeedingEndTime          string
		AnimalFeedingPeriodHourMinute string
	}{}
	if err := c.Bind(&feedingTimes); err != nil {
		return err
	}
	c.Logger().Debugf("feedingTimes: %v", feedingTimes)
	animal.FeedingStart = timeToNullTime(feedingTimes.AnimalFeedingStartTime)
	animal.FeedingEnd = timeToNullTime(feedingTimes.AnimalFeedingEndTime)
	animal.FeedingPeriod = timeToMinutes(feedingTimes.AnimalFeedingPeriodHourMinute)

	// Decode additonal form param
	backUrl := struct {
		BackUrl nulls.String
	}{}
	// load backUrl
	if err := c.Bind(&backUrl); err != nil {
		return err
	}
	c.Logger().Debugf("Back: %v", backUrl)

	// Fix link
	animal.Discovery.Discoverer.ID = animal.Discovery.DiscovererID

	// Validate the data from the html form
	updateModels := []interface{}{
		&animal.Discovery.Discoverer,
		&animal.Discovery,
		&animal.Intake,
		animal.Outtake,
		animal,
	}

	var verrs *validate.Errors
	for _, m := range updateModels {
		if reflect.ValueOf(m).IsNil() {
			continue
		}
		c.Logger().Debugf("Updating %v", m)
		verrs, err = tx.Eager().ValidateAndUpdate(m)
		if err != nil {
			return err
		}
		if verrs.HasAny() {
			break
		}
	}

	c.Logger().Debugf("originalCage: %v - cage: %v", originalCage, animal.Cage)

	// Load care types
	careTypes, err := caretypes(c)
	if err != nil {
		return err
	}

	// Create new defailt care if animal was moved
	if !verrs.HasAny() && originalCage.String != "" && animal.Cage.String != originalCage.String {
		c.Logger().Debugf("Creating new care for cage move for animalID %d", animal.ID)
		care := &models.Care{}
		care.Animal = *animal
		care.AnimalID = animal.ID
		care.Date = models.NowOffset()
		care.Note = nulls.NewString(fmt.Sprintf("Cage %s => %s", originalCage.String, animal.Cage.String))

		// Set care to default
		for _, careType := range *careTypes {
			ctn := strings.ToLower(careType.Name)
			// try to find move
			if strings.Contains(ctn, "move") || strings.Contains(ctn, "déplacement") {
				care.Type = careType
				care.TypeID = careType.ID
				break
			}
			// fall back to default
			if careType.Def {
				care.Type = careType
				care.TypeID = careType.ID
			}
		}

		c.Logger().Debugf("Creating new care for cage move for animalID %d: %v", animal.ID, care)
		verrs, err = tx.Eager().ValidateAndCreate(care)
		if err != nil {
			return err
		}
		auditAnimalChange(c, tx, animal.ID, models.AuditEntityCare, auditEntityID(care.ID), models.AuditActionCreate, nil, auditCareProjection(*care))
	}

	c.Logger().Debugf("originalCage: %v - cage: %v", originalCage, animal.Cage)
	// Create new defailt care if animal feeding is updated
	if !verrs.HasAny() && animal.Feeding.String != originalFeeding.String && animal.Feeding.String != "" {
		c.Logger().Debugf("Creating new care for updated feeding animalID %d", animal.ID)
		care := &models.Care{}
		care.Animal = *animal
		care.AnimalID = animal.ID
		care.Date = models.NowOffset()
		care.Note = animal.Feeding

		// Set care to default
		for _, careType := range *careTypes {
			ctn := strings.ToLower(careType.Name)
			// try to find move
			if strings.Contains(ctn, "feedings") || strings.Contains(ctn, "alimentation") {
				care.Type = careType
				care.TypeID = careType.ID
				break
			}
			// fall back to default
			if careType.Def {
				care.Type = careType
				care.TypeID = careType.ID
			}
		}

		c.Logger().Debugf("Creating new care for cage move for animalID %d: %v", animal.ID, care)
		verrs, err = tx.Eager().ValidateAndCreate(care)
		if err != nil {
			return err
		}
		auditAnimalChange(c, tx, animal.ID, models.AuditEntityCare, auditEntityID(care.ID), models.AuditActionCreate, nil, auditCareProjection(*care))
	}

	if verrs.HasAny() {
		return responder.Wants("html", func(c buffalo.Context) error {
			// Make the errors available inside the html template
			c.Set("errors", verrs)

			// Render again the edit.html template that the user can
			// correct the input.
			c.Set("animal", animal)

			return c.Render(http.StatusUnprocessableEntity, r.HTML("/animals/edit.plush.html"))
		}).Wants("json", func(c buffalo.Context) error {
			return c.Render(http.StatusUnprocessableEntity, r.JSON(verrs))
		}).Wants("xml", func(c buffalo.Context) error {
			return c.Render(http.StatusUnprocessableEntity, r.XML(verrs))
		}).Respond(c)
	}

	// Audit log: record what changed (best effort). Entries without any
	// detectable change are skipped inside the helper.
	auditAnimalChange(c, tx, animal.ID, models.AuditEntityAnimal, auditEntityID(animal.ID), models.AuditActionUpdate, auditAnimalProjection(oldAnimal), auditAnimalProjection(*animal))
	auditAnimalChange(c, tx, animal.ID, models.AuditEntityDiscoverer, animal.Discovery.DiscovererID.String(), models.AuditActionUpdate, oldDiscoverer, animal.Discovery.Discoverer)
	auditAnimalChange(c, tx, animal.ID, models.AuditEntityDiscovery, animal.DiscoveryID.String(), models.AuditActionUpdate, auditDiscoveryProjection(oldDiscovery), auditDiscoveryProjection(animal.Discovery))
	auditAnimalChange(c, tx, animal.ID, models.AuditEntityIntake, animal.IntakeID.String(), models.AuditActionUpdate, oldIntake, animal.Intake)
	if oldOuttake != nil && animal.Outtake != nil {
		outtakeID := ""
		if animal.OuttakeID.Valid {
			outtakeID = animal.OuttakeID.UUID.String()
		}
		auditAnimalChange(c, tx, animal.ID, models.AuditEntityOuttake, outtakeID, models.AuditActionUpdate, auditOuttakeProjection(*oldOuttake), auditOuttakeProjection(*animal.Outtake))
	}

	// Publish status change event if outtake was added/removed
	if originalOuttakeID.Valid != animal.OuttakeID.Valid {
		var previousStatus, currentStatus string
		if originalOuttakeID.Valid {
			previousStatus = "released"
		} else {
			previousStatus = "in_care"
		}
		if animal.OuttakeID.Valid {
			currentStatus = "released"
		} else {
			currentStatus = "in_care"
		}
		if err := PublishAnimalStatusChangedEvent(tx, animal, previousStatus, currentStatus, GetCurrentUser(c)); err != nil {
			c.Logger().Warnf("Failed to publish animal_status_changed event: %v", err)
		}
	}

	// Full-state event: every successful edit (cage, zone, species, intake,
	// outtake, discovery fields, ...) is synced to the console. The
	// content-hash dedupe turns a no-op save into no event.
	publishAnimalStateEventWarn(c, tx, animal.ID)

	// Annual statistics tables count animals: drop the per-year cache.
	InvalidateAnnualStatsCache()

	return responder.Wants("html", func(c buffalo.Context) error {
		// If there are no errors set a success message
		c.Flash().Add("success", T.Translate(c, "animal.updated.success"))
		if backUrl.BackUrl.Valid {
			return c.Redirect(http.StatusSeeOther, backUrl.BackUrl.String)
		}
		// and redirect to the show page
		return c.Redirect(http.StatusSeeOther, "/animals/%v", animal.ID)
	}).Wants("json", func(c buffalo.Context) error {
		return c.Render(http.StatusOK, r.JSON(animal))
	}).Wants("xml", func(c buffalo.Context) error {
		return c.Render(http.StatusOK, r.XML(animal))
	}).Respond(c)
}

// Destroy deletes a Animal from the DB. This function is mapped
// to the path DELETE /animals/{animal_id}
func (v AnimalsResource) Destroy(c buffalo.Context) error {
	// Admin only
	if !GetCurrentUser(c).Admin {
		return c.Error(http.StatusForbidden, fmt.Errorf("restricted"))
	}

	// Get the DB connection from the context
	tx, ok := c.Value("tx").(*pop.Connection)
	if !ok {
		return fmt.Errorf("no transaction found")
	}

	// Load animal
	animal, err := v.loadAnimal(c.Param("animal_id"), c)
	if err != nil {
		return err
	}

	// Find 1st error
	ot := &models.Outtaketype{}
	if err := tx.Where("error = ?", true).First(ot); err != nil {
		return c.Error(http.StatusNotFound, err)
	}

	// Audit snapshots before attaching the error outtake.
	animalBefore := *animal

	animal.Outtake = &models.Outtake{
		Animal: *animal,
		Date:   models.NowOffset(),
		Type:   *ot,
		TypeID: ot.ID,
	}

	if err := tx.Eager().Create(animal.Outtake); err != nil {
		return err
	}

	// Audit log: destroy = error outtake creation + animal status update
	auditAnimalChange(c, tx, animal.ID, models.AuditEntityOuttake, animal.Outtake.ID.String(), models.AuditActionCreate, nil, auditOuttakeProjection(*animal.Outtake))
	auditAnimalChange(c, tx, animal.ID, models.AuditEntityAnimal, auditEntityID(animal.ID), models.AuditActionUpdate, auditAnimalProjection(animalBefore), auditAnimalProjection(*animal))

	// Publish animal_died event for destroyed animals
	if err := PublishAnimalDiedEvent(tx, animal, GetCurrentUser(c)); err != nil {
		c.Logger().Warnf("Failed to publish animal_died event: %v", err)
	}

	/*animal.OuttakeID = nulls.NewUUID(animal.Outtake.ID)
	if err := tx.Eager().Update(animal); err != nil {
		return err
	}*/

	// Annual statistics tables count animals: drop the per-year cache.
	InvalidateAnnualStatsCache()

	return responder.Wants("html", func(c buffalo.Context) error {
		// If there are no errors set a flash message
		c.Flash().Add("success", T.Translate(c, "animal.destroyed.success"))

		// Redirect to the index page
		return c.Redirect(http.StatusSeeOther, "/animals")
	}).Wants("json", func(c buffalo.Context) error {
		return c.Render(http.StatusOK, r.JSON(animal))
	}).Wants("xml", func(c buffalo.Context) error {
		return c.Render(http.StatusOK, r.XML(animal))
	}).Respond(c)
}
